SELECT * FROM jsonb_to_recordset($repairs$[{"id":"e75d7e05-821d-4e91-b459-1c8e9c3657b6","name":"李明哲","claim_key":"cec-platform:2022:votetw-candidate-1d141fd3c7426d4a","person_id":"6189033d-7ca8-4f76-80c1-56d1bfef4311","candidate_id":"fafa9b60-8808-45e0-877f-a339af9ac49a","candidate_person_id":"6189033d-7ca8-4f76-80c1-56d1bfef4311","canonical_person_id":"6fbed1cc-d8b6-4be7-9860-e002016c8cb0","candidate_name":"李明哲","candidate_no":"7","race_id":"71ec1328-47e0-4c6a-b3ac-16f809e2ef79","election_id":"4335e772-86a7-49d0-b09d-55481719ae84","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/11%E9%9B%B2%E6%9E%97%E7%B8%A3/%E9%9B%B2%E6%9E%97%E7%B8%A3%E7%AC%AC04%E9%81%B8%E5%8D%80.pdf","source_sha256":"1e7d987b6abe14912e587829a8617216eca9bb864fee809076c5f8b456f7f5b7","after_source_sha256":"1e7d987b6abe14912e587829a8617216eca9bb864fee809076c5f8b456f7f5b7","after_text":"1. 推動文創古城翻新\n農業加值、宗教加值、歷史加值；敦促縣府再造西螺風華，提升在地自我認同的光榮感；文創、經濟加值，結合觀光帶動濁水溪畔三鄉鎮發展。\n\n2. 改造生活、收入增加\n持續敦促政府建立蔬果價格崩盤預防機制；監督提高交通、水利、防洪、農水路養護基礎建設預算比例；擴大辦理長輩關懷據點；敦促縣府把關國土計畫法，保障農民生存權益。\n\n3. 加速西螺觀光發展\n持續敦促縣府爭取高鐵班次，新增高鐵西螺接駁公車；發揚西螺七崁文化，推動七崁武術文化園區。\n\n4. 落實耕耘基層教育\n敦促縣府營造各校溫馨的閱讀空間，培養學生獨立思考基礎；加強改善弱勢學生受教不平等；持續推動武術扎根校園計畫；建構校園與社區優質體育運動環境；培養學生強健體魄與良好運動觀念。\n\n西螺風華再升級，文創經濟再翻新；深耕在地李明哲，睿智幸福好抉擇。","patch":{"items":["推動文創古城翻新 農業加值、宗教加值、歷史加值；敦促縣府再造西螺風華，提升在地自我認同的光榮感；文創、經濟加值，結合觀光帶動濁水溪畔三鄉鎮發展。","改造生活、收入增加 持續敦促政府建立蔬果價格崩盤預防機制；監督提高交通、水利、防洪、農水路養護基礎建設預算比例；擴大辦理長輩關懷據點；敦促縣府把關國土計畫法，保障農民生存權益。","加速西螺觀光發展 持續敦促縣府爭取高鐵班次，新增高鐵西螺接駁公車；發揚西螺七崁文化，推動七崁武術文化園區。","落實耕耘基層教育 敦促縣府營造各校溫馨的閱讀空間，培養學生獨立思考基礎；加強改善弱勢學生受教不平等；持續推動武術扎根校園計畫；建構校園與社區優質體育運動環境；培養學生強健體魄與良好運動觀念。"],"platformIntro":"西螺風華再升級，文創經濟再翻新；深耕在地李明哲，睿智幸福好抉擇。","contentSplit":{"method":"source_checked_review_directed_repair_20260930","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"platformReviewRepair":{"version":"2022-platform-review-20260930","reviewDocumentSha256":"2c05197f93e3753024b9201720687372f47be