ttps://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC05-07%E9%81%B8%E8%88%89%E5%8D%80.pdf","file":"tmp/cec-representative-platforms/2022-councilor/pdfs/2975fd69b0093e4df9c24143.pdf","page":2,"sha256":"79d7c4a07d5817657dfddf890e83885811987ef22d2324be829acb54680ab4a4","layoutFile":null,"extractionMethod":"needs_manual_localization"},"contentSplit":{"method":"source_checked_review_directed_repair_20260930","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"platformReviewRepair":{"version":"2022-platform-review-20260930","reviewDocumentSha256":"2c05197f93e3753024b9201720687372f47be16dbbb421a301b1ef274575dfc0","reviewNumber":8,"changes":["更正保存PDF來源頁碼為本人所在第2頁；第4項沿用原件字句"],"remainingIssues":["第4項語意仍不完整；PDF本人欄同字，不能猜改。"],"previousContentSplit":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"basis":"使用者要求依覆核文件定向修正；以既有來源與代理核對為依據，保留原公開審核狀態，不宣稱新增人工逐項核准。"}},"items":["觀光推動 結合農漁業輔導產銷班推廣在地特產。","要求政府重視提升在地醫療。","爭取快速道路及鐵路南延恆春半島。","要求原有部落劃墾丁國家公園。","提倡環境保育觀光資源永續發展。","爭取經費推廣恆春半島六鄉鎮傳統文化。","爭取經費整治產業道路及各港口清淤使農漁民安心作業。","爭取經費提倡地方教育資源及提升各項體育發展效能。"],"after_json_md5":"34db6ffd1760ae17808f7dc8a4b62e9c","before_json_md5":"15af6272e47be36b3f73677df76d7321","before_text_md5":"81a96678833daf70fe5285eedc1ff58c","production_before_text_md5":"74fb5a203fb6efe7686014170f474bbe","production_before_json_md5":"107214d2036a29091ed27e07ceb6fbc4","production_after_json_md5":"140c04978c607b53a0d929602813489d"},{"id":"08278386-d6ca-4fbd-bf2e-ad2d62e2b363","name":"游吉祥","claim_key":"cec-platform:2022:votetw-candidate-5d2c77e063c98797","person_id":"9df321f9-ffbb-4123-9a57-26f0e18cf4c7","candidate_id":"b5a5e4f4-47b4-422e-a859-c48d16dbeeef","candidate_person_id":"9df321f9-ffbb-4123-9a57-26f0e18cf4c7","canonical_person_id":"590a2360-b7ed-4239-be2f-c33f525482cb","candidate_name":"游吉祥","candidate_no":"1","race_id":"c0d6ff24-1ccc-4ef3-acea-c5e722075050","election_id":"31731000-2caa-4be4-814a-f00b6d33205b","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/14%E5%AE%9C%E8%98%AD%E7%B8%A3/%E5%AE%9C%E8%98%AD%E7%B8%A3%E7%AC%AC13%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"0ba7cc62cde87da0c70890def6efef6969d165783b6a3361f45082a80c9f561e","after_source_sha256":"0ba7cc62cde87da0c70890def6efef6969d165783b6a3361f45082a80c9f561e","after_text":"「理性問政，專業堅持；清廉熱忱，族人第一；為您做事，我的榮幸。」\n1. 強化原住民主體性，落實推動原住民政策主流化。\n2. 監督縣政，強調公開、透明、效率與品質，以落實原鄉各項公共政策之目標。\n3. 爭取中央與縣府經費，改善部落基礎建設，營造友善環境，保障族人基本生活品質。\n4. 活用大南澳地區獨特的山、河、海自然環境及原、客、閩的多元文化特色，結合地方創生計畫，發展農、漁、林、休閒運動、文化體驗及生態旅遊等多元產業，優化原鄉產業經濟，並積極培力在地人才，延攬青年回鄉，吸引企業進駐，活力部落，永續原鄉。\n5. 重視社會福利政策，落實長者照護及弱勢關懷，保障族人生活品質，照護原鄉、守護生命。\n6. 提升全鄉醫療品質，推動遠距醫療服務，善用科技補足人力，營造醫療平權、就醫無礙、如醫到府的友善健康環境。\n7. 強化國土計畫法，重視原鄉區域計畫，捍衛族人居住正義，保障族人生存權。\n8. 充實原鄉學校軟硬體設施，建構優質的學習環境，提升教師專業發展，激發學生多元智慧，落實教育目標。\n9. 積極推動民族教育，發展民族教育課程方案與內容，建構民族教育知識系統，落實民族教育完整學習體制之目標。\n10. 積極協助推動蘇花安－東澳至南澳段廊道計畫，提供族人一條安全舒適的道路。","patch":{"items":["強化原住民主體性，落實推動原住民政策主流化。","監督縣政，強調公開、透明、效率與品質，以落實原鄉各項公共政策之目標。","爭取中央與縣府經費，改善部落基礎建設，營造友善環境，保障族人基本生活品質。","活用大南澳地區獨特的山、河、海自然環境及原、客、閩的多元文化特色，結合地方創生計畫，發展農、漁、林、休閒運動、文化體驗及生態旅遊等多元產業，優化原鄉產業經濟，並積極培力在地人才，延攬青年回鄉，吸引企業進駐，活力部落，永續原鄉。","重視社會福利政策，落實長者照護及弱勢關懷，保障族人生活品質，照護原鄉、守護生命。","提升全鄉醫療品質，推動遠距醫療服務，善用科技補足人力，營造醫療平權、就醫無礙、如醫到府的友善健康環境。","強化國土計畫法，重視原鄉區域計畫，捍衛族人居住正義，保障族人生存權。","充實原鄉學校軟硬體設施，建構優質的學習環境，提升教師專業發展，激發學生多元智慧，落實教育目標。","積極推動民族教育，發展民族教育課程方案與內容，建構民族教育知識系統，落實民族教育完整學習體制之目標。","積極協助推動蘇花安－東澳至南澳段廊道計畫，提供族人一條安全舒適的道路。"],"platformIntro":"「理性問政，專業堅持；清廉熱忱，族人第一；為您做事，我的榮幸。」","contentSplit":{"method":"source_checked_review_directed_repair_20260930","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"platformReviewRepair":{"version":"2022-platform-review-20260930","reviewDocumentSha256":"2c05197f93e3753024b9201720687372f47be16dbbb421a301b1ef274575dfc0","reviewNumber":10,"changes":["將競選宣言由投票項移至前言，十項編號政策保留"],"remainingIssues":[],"previousContentSplit":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"basis":"使用者要求依覆核文件定向修正；以既有來源與代理核對為依據，保留原公開審核狀態，不宣稱新增人工逐項核准。"}},"items":["強化原住民主體性，落實推動原住民政策主流化。","監督縣政，強調公開、透明、效率與品質，以落實原鄉各項公共政策之目標。","爭取中央與縣府經費，改善部落基礎建設，營造友善環境，保障族人基本生活品質。","活用大南澳地區獨特的山、河、海自然環境及原、客、閩的多元文化特色，結合地方創生計畫，發展農、漁、林、休閒運動、文化體驗及生態旅遊等多元產業，優化原鄉產業經濟，並積極培力在地人才，延攬青年回鄉，吸引企業進駐，活力部落，永續原鄉。","重視社會福利政策，落實長者照護及弱勢關懷，保障族人生活品質，照護原鄉、守護生命。","提升全鄉醫療品質，推動遠距醫療服務，善用科技補足人力，營造醫療平權、就醫無礙、如醫到府的友善健康環境。","強化國土計畫法，重視原鄉區域計畫，捍衛族人居住正義，保障族人生存權。","充實原鄉學校軟硬體設施，建構優質的學習環境，提升教師專業發展，激發學生多元智慧，落實教育目標。","積極推動民族教育，發展民族教育課程方案與內容，建構民族教育知識系統，落實民族教育完整學習體制之目標。","積極協助推動蘇花安－東澳至南澳段廊道計畫，提供族人一條安全舒適的道路。"],"after_json_md5":"e27699563d487d68876172f4a2140396","before_json_md5":"00170516a02fe65ac1f87de4f26d3457","before_text_md5":"95a5e613de7d04cdf30a3cb630fc74e5","production_before_text_md5":"95a5e613de7d04cdf30a3cb630fc74e5","production_before_json_md5":"09cc6d8ce00ec860e254a9ca01674374","production_after_json_md5":"fead8c33552e22128506ea100ca9fbb6"},{"id":"2657d341-419c-4c90-bf29-02c25b550521","name":"蔣家煌","claim_key":"cec-platform:2022:votetw-candidate-6d7cc4eb603d19e4","person_id":"ef327839-1e18-4adb-86a5-c8c1b5960020","candidate_id":"7a46360e-6a7e-49de-9c65-b7bb220c7268","candidate_person_id":"ef327839-1e18-4adb-86a5-c8c1b5960020","canonical_person_id":"1aed81f3-d5ab-4916-b34b-f2aab2148f1f","candidate_name":"蔣家煌","candidate_no":"10","race_id":"af912913-d553-499f-b5b8-21cc5a803fb6","election_id":"ed01d504-4751-4ae3-9ef3-d40bbc3b0905","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%801.pdf","source_sha256":"449718253f8db87d6eec3403754a97ee094ab80b1a01ddf58c9365022c1cbc8c","after_source_sha256":"449718253f8db87d6eec3403754a97ee094ab80b1a01ddf58c9365022c1cbc8c","after_text":"1、服務基