idate_id":"0882b93c-c453-4bb5-b258-9ae706f9dd12","candidate_person_id":"e571c990-ce0c-4334-8026-c838d1dc4d6b","canonical_person_id":"805da301-5c8c-4d8a-a0f5-987fc7544266","candidate_name":"段孝芳","candidate_no":"8","race_id":"7cc947b0-73aa-46f2-bda8-b4c532f18c94","election_id":"b2b7b1c9-5278-4699-a501-31520945380e","source_url":"https://www.hsinchu-cc.gov.tw/tc/councilor.aspx?mid=39&c=12","source_sha256":null,"after_source_sha256":"9758509114bf2bde7cec77912f6334b1d186df0663cd85292b1c7322d83c500b","after_text":"1.強力要求增設科學園區聯外道路，解決園區周邊交通壅塞問題。\n2.督促園區污水廢氣排放，落實環境保護工作。\n3. 敦促市府加強開辦社區關懷據點，推動老人健康篩檢，加強體適能檢測與正確運動指導，增加失智症篩檢量表，延緩失能失智，落實老人照護。\n4.敦促市府廣建日照中心達到一國中學區一日照。\n5.敦促市府於關埔二期增設國中小學，以利學童就近入學。\n6.爭取打造友善公車，透過科技輔助及政府監督，提升公車文化。\n7.敦促市府加速興建汙水下水道系統，改善區域排水。\n8.敦促市府廣設汽車充電樁。","patch":{"items":["強力要求增設科學園區聯外道路，解決園區周邊交通壅塞問題。","督促園區污水廢氣排放，落實環境保護工作。","敦促市府加強開辦社區關懷據點，推動老人健康篩檢，加強體適能檢測與正確運動指導，增加失智症篩檢量表，延緩失能失智，落實老人照護。","敦促市府廣建日照中心達到一國中學區一日照。","敦促市府於關埔二期增設國中小學，以利學童就近入學。","爭取打造友善公車，透過科技輔助及政府監督，提升公車文化。","敦促市府加速興建汙水下水道系統，改善區域排水。","敦促市府廣設汽車充電樁。"],"platformIntro":"","sourceDocument":{"file":"tmp/cec-representative-platforms/2022-councilor/pdfs/09a686a33de0a2229f93152b.pdf","url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/21%E6%96%B0%E7%AB%B9%E5%B8%82/%E6%96%B0%E7%AB%B9%E5%B8%82%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf","matchMethod":"text_layer","decodedPath":"01選舉公報/06縣市議員/111年/21新竹市/新竹市第01選舉區.pdf","sha256":"9758509114bf2bde7cec77912f6334b1d186df0663cd85292b1c7322d83c500b","bytes":12240883,"exactNameFound":true,"page":1},"contentSplit":{"method":"source_checked_review_directed_repair_20260930","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","reasonCodes":["heading_or_slogan"],"excludedItemCount":1}},"platformReviewRepair":{"version":"2022-platform-review-20260930","reviewDocumentSha256":"2c05197f93e3753024b9201720687372f47be