ce_sha256":"26b9bf6e9261a6130d65efeb47240dd61e0d4f75e7d544415a8c1cb85ffb3836","after_text":"教育\n1. 爭取營養午餐補助。\n2. 教師權益維護。\n3. 學校設備升級2.0。\n4. 爭取體育發展基金。\n\n老人福利\n1. 老人年金發放持續推動。\n2. 持續爭取老人假牙補助津貼。\n3. 加強老人醫療及安養照顧。\n4. 推動爭取失智老人配戴定位失智手環。\n5. 加強友善老人環境，讓戶外活動的人們更安心。\n\n民生福利\n1. 協助與關懷勞工問題，保障勞資雙方權益。\n2. 照顧弱勢族群，協助單親、中低收入戶及身心障礙者得到應有的權益。\n3. 設立婦女保護安立之家，協助家暴及失婚婦女身心重建。\n4. 爭取生育補助1胎2萬元、第2胎3萬元、第3胎5萬元。\n5. 全縣民平安保險35萬元持續辦。\n6. 加強警消設備，確保治安及人民生活安全無虞。","patch":{"items":["教育：爭取營養午餐補助。","教育：教師權益維護。","教育：學校設備升級2.0。","教育：爭取體育發展基金。","老人福利：老人年金發放持續推動。","老人福利：持續爭取老人假牙補助津貼。","老人福利：加強老人醫療及安養照顧。","老人福利：推動爭取失智老人配戴定位失智手環。","老人福利：加強友善老人環境，讓戶外活動的人們更安心。","民生福利：協助與關懷勞工問題，保障勞資雙方權益。","民生福利：照顧弱勢族群，協助單親、中低收入戶及身心障礙者得到應有的權益。","民生福利：設立婦女保護安立之家，協助家暴及失婚婦女身心重建。","民生福利：爭取生育補助1胎2萬元、第2胎3萬元、第3胎5萬元。","民生福利：全縣民平安保險35萬元持續辦。","民生福利：加強警消設備，確保治安及人民生活安全無虞。"],"platformIntro":"","sourceDocument":{"url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/07%E6%96%B0%E7%AB%B9%E7%B8%A3/%E6%96%B0%E7%AB%B9%E7%B8%A3%E7%AC%AC08%E9%81%B8%E8%88%89%E5%8D%80.pdf","file":"tmp/cec-representative-platforms/2022-councilor/pdfs/7fb4e9a0348d5ae6a3b52311.pdf","page":1,"sha256":"26b9bf6e9261a6130d65efeb47240dd61e0d4f75e7d544415a8c1cb85ffb3836","layoutFile":null,"extractionMethod":"verified_candidate_column_visual","candidateNumber":4,"candidateName":"上官秋燕","district":"第8選舉區"},"contentSplit":{"method":"source_checked_review_directed_repair_20260930","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","reasonCodes":["heading_or_slogan"],"excludedItemCount":2}},"platformReviewRepair":{"version":"2022-platform-review-20260930","reviewDocumentSha256":"2c05197f93e3753024b9201720687372f47be16dbbb421a301b1ef274575dfc0","reviewNumber":131,"changes":["教育第3項與民生福利第5項均由官方公報補回，插入原段順序。"],"remainingIssues":[],"previousContentSplit":{"method":"numbered","version":"election-content-items-v1","confidence"