%E8%88%89%E5%8D%80.pdf","source_sha256":"c02e3d0dca8200ef9f10e1435d7eb4d2a00cd9f39f7c552ec53ea5763633e1db","after_source_sha256":"c02e3d0dca8200ef9f10e1435d7eb4d2a00cd9f39f7c552ec53ea5763633e1db","after_text":"天職信念,全職全時服務。\n1. 推動增加幼兒公共托育家園。\n2. 推動提升魚池、水里、集集、信義、地方建設。\n3. 縣內國中小學軟硬體設備及改善。\n4. 關懷新住民增加輔導課程。\n5. 勤走基層、為民喉舌、爭取經費、建設地方。\n6. 重視老人社會福利、關懷弱勢。","patch":{"items":["推動增加幼兒公共托育家園。","推動提升魚池、水里、集集、信義、地方建設。","縣內國中小學軟硬體設備及改善。","關懷新住民增加輔導課程。","勤走基層、為民喉舌、爭取經費、建設地方。","重視老人社會福利、關懷弱勢。"],"platformIntro":"","sourceDocument":{"url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/10%E5%8D%97%E6%8A%95%E7%B8%A3/%E5%8D%97%E6%8A%95%E7%B8%A3%E7%AC%AC3.4%E9%81%B8%E8%88%89%E5%8D%80.pdf","file":"tmp/cec-representative-platforms/2022-councilor/pdfs/c233328cd004097617c87245.pdf","page":1,"sha256":"c02e3d0dca8200ef9f10e1435d7eb4d2a00cd9f39f7c552ec53ea5763633e1db","layoutFile":null,"extractionMethod":"verified_candidate_column_visual","candidateNumber":4,"candidateName":"王秋淑","district":"第3選舉區"},"contentSplit":{"method":"source_checked_review_directed_repair_20260930","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","reasonCodes":["heading_or_slogan"],"excludedItemCount":2}},"platformReviewRepair":{"version":"2022-platform-review-20260930","reviewDocumentSha256":"2c05197f93e3753024b9201720687372f47be16dbbb421a301b1ef274575dfc0","reviewNumber":134,"changes":["依官方公報原列位置補回 1 項：重視老人社會福利、關懷弱勢。"],"remainingIssues":[],"previousContentSplit":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","reasonCodes":["heading_or_slogan"],"excludedItemCount":2}},"basis":"使用者要求依覆核文件定向修正；以既有來源與代理核對為依據，保留原公開審核狀態，不宣稱新增人工逐項核准。"}},"items":["推動增加幼兒公共托育家園。","推動提升魚池、水里、集集、信義、地方建設。","縣內國中小學軟硬體設備及改善。","關懷新住民增加輔導課程。","勤走基層、為民喉舌、爭取經費、建設地方。","重視老人社會福利、關懷弱勢。"],"after_json_md5":"891df71fefc237bc678de1fe6d3419f4","before_json_md5":"b289aec30d6aa60ca2475a1ea8265bd6","before_text_md5":"5444c6ed8fcd98d6ac9e4a2493d49d2b","production_before_text_md5":"e5944b8dedb21668fb5474ae045039a2","production_before_json_md5":"7f5aff2b9cdebd405cf3cb1f9bfc1372","production_after_json_md5":"4a7d4c9d1a76d2e7e1bfea9aee78010e"}]$repairs$::jsonb)
AS r(id uuid,name text,claim_key text,person_id uuid,candidate_id uuid,candidate_person_id uuid,canonical_person_id uuid,candidate_name text,candidate_no text,
 race_id uuid,election_id uuid,source_url text,source_sha256 text,after_source_sha256 text,after_text text,patch jsonb,items jsonb,
 before_text_md5 text,before_json_md5 text,after_json_md5 text,
 production_before_text_md5 text,production_before_json_md5 text,production_after_json_md5 text);
LOCK TABLE public.platform_fulfillment_votes IN SHARE MODE;
LOCK TABLE public.person_merge_decisions IN SHARE MODE;
DO $guard$
BEGIN
 IF (SELECT count(*) FROM reviewed_councilor_repairs)<>125
 OR (SELECT count(DISTINCT id) FROM reviewed_councilor_repairs)<>125
 OR (SELECT sum(jsonb_array_length(items)) FROM reviewed_councilor_repairs)<>1415 THEN
  RAISE EXCEPTION 'Unexpected reviewed councilor repair scope';
 END IF;
 PERFORM c.id FROM public.person_claims c JOIN reviewed_councilor_repairs r ON r.id=c.id ORDER BY c.id FOR UPDATE OF c;
 -- 父登記與選區／選舉及 canonical 關係亦鎖住，防止驗證後並行改綁。
 PERFORM k.id FROM public.candidates k JOIN reviewed_councilor_repairs r ON r.candidate_id=k.id ORDER BY k.id FOR SHARE OF k;
 PERFORM race.id FROM public.races race WHERE race.id IN (SELECT race_id FROM reviewed_councilor_repairs) ORDER BY race.id FOR SHARE OF race;
 PERFORM e.id FROM public.elections e WHERE e.id IN (SELECT election_id FROM reviewed_councilor_repairs) ORDER BY e.id FOR SHARE OF e;
 IF EXISTS (
  SELECT 1 FROM reviewed_councilor_repairs r LEFT JOIN public.person_claims c ON c.id=r.id
  LEFT JOIN public.candidates k ON k.id=c.candidate_id
  LEFT JOIN public.person_canonical_map cm ON cm.person_id=k.person_id
  LEFT JOIN public.person_canonical_map pm ON pm.person_id=c.person_id
  LEFT JOIN public.races race ON race.id=k.race_id
  LEFT JOIN public.elections e ON e.id=race.election_id
  WHERE c.id IS NULL OR c.claim_key IS DISTINCT FROM r.claim_key
  OR c.person_id IS DISTINCT FROM r.person_id OR c.candidate_id IS DISTINCT FROM r.candidate_id
  OR k.person_id IS DISTINCT FROM r.candidate_person_id
  OR (k.candidate_name IS DISTINCT FROM r.candidate_name AND NOT (k.candidate_name IS NULL
    AND md5(c.claim_json::text) IN (r.production_before_json_md5,r.production_after_json_md5)))
  OR k.candidate_no::text IS DISTINCT FROM r.candidate_no
  OR coalesce(cm.canonical_person_id,k.person_id) IS DISTINCT FROM coalesce(pm.canonical_person_id,c.person_id)
  OR coalesce(cm.canonical_person_id,k.person_id) IS DISTINCT FROM r.canonical_person_id
  OR k.race_id IS DISTINCT FROM r.race_id OR e.id IS DISTINCT FROM r.election_id
  OR e.year IS DISTINCT FROM 2022 OR race.race_type IS DISTINCT FROM 'councilor_district'
  OR k.is_elected IS DISTINCT FROM true OR k.election_result IS DISTINCT FROM 'elected' OR k.is_public IS DISTINCT FROM true
  OR c.claim_type IS DISTINCT FROM 'platform' OR c.review_status IS DISTINCT FROM 'verified'
  OR c.visibility IS DISTINCT FROM 'public' OR c.is_public IS DISTINCT FROM true
  OR c.source_url IS DISTINCT FROM r.source_url
  OR c.claim_json#>>'{sourceDocument,sha256}' IS DISTINCT FROM
    CASE WHEN md5(c.claim_json::text) IN (r.after_json_md5,r.production_after_json_md5) THEN r.after_source_sha256 ELSE r.source_sha256 END
  OR ((md5(c.claim_value)=r.before_text_md5 AND md5(c.claim_json::text)=r.before_json_md5)
   OR (md5(c.claim_value)=r.production_before_text_md5 AND md5(c.claim_json::text)=r.production_before_json_md5)
   OR (c.claim_value=r.after_text AND md5(c.claim_json::text) IN (r.after_json_md5,r.production_after_json_md5))) IS NOT TRUE
 ) THEN RAISE EXCEPTION 'Reviewed councilor baseline, source, approval or identity changed'; END IF;
 IF EXISTS(SELECT 1 FROM reviewed_councilor_repairs r JOIN public.person_claims c ON c.id=r.id
  JOIN public.platform_fulfillment_votes v ON v.claim_id=c.id
  WHERE md5(c.claim_json::text) NOT IN (r.after_json_md5,r.production_after_json_md5)) THEN
  RAISE EXCEPTION 'Existing platform votes require explicit item mapping';
 END IF;
END;
$guard$;
UPDATE public.person_claims c SET claim_value=r.after_text,claim_json=c.claim_json||r.patch,updated_at=now()
FROM reviewed_councilor_repairs r WHERE c.id=r.id AND (md5(c.claim_json::text) NOT IN (r.after_json_md5,r.production_after_json_md5) OR c.claim_value IS DISTINCT FROM r.after_text);
DO $verify$
DECLARE r record; actual_items jsonb;
BEGIN
 FOR r IN SELECT * FROM reviewed_councilor_repairs LOOP
  IF NOT EXISTS(SELECT 1 FROM public.person_claims c WHERE c.id=r.id
   AND c.claim_value=r.after_text AND md5(c.claim_json::text) IN (r.after_json_md5,r.production_after_json_md5)) THEN
   RAISE EXCEPTION 'Reviewed councilor post-update mismatch: %',r.id;
  END IF;
  SELECT jsonb_agg(f.promise_text ORDER BY f.display_order)
  INTO actual_items FROM published.platform_fulfillment_results(r.id) f;
  IF actual_items IS DISTINCT FROM r.items THEN
   RAISE EXCEPTION 'Repaired items not readable: %',r.id;
  END IF;
 END LOOP;
END;
$verify$;
COMMIT;
